const WORK_LANES=[
  {id:"captured",label:"Captured",statuses:["captured"]},
  {id:"assigned",label:"Assigned",statuses:["assigned"]},
  {id:"in_progress",label:"In progress",statuses:["in_progress"]},
  {id:"review",label:"Review",statuses:["review","client_review"]},
  {id:"shipped",label:"Shipped",statuses:["shipped"]}
];
let workData={work:[],projects:[],reviews:[],loaded:false,error:null},workView="board";
function normalStatus(value){return String(value||"captured").toLowerCase().replaceAll(" ","_")}
function displayStatus(value){return normalStatus(value).replaceAll("_"," ").replace(/^./,x=>x.toUpperCase())}
function projectName(id){const item=workData.projects.find(x=>x.id===id);return item?item.name:"No project"}
function workOwner(item){return item.owner_person_id||item.assignee_person_id||item.assignee_id||"Unassigned"}
function workDeadline(item){return item.deadline||item.needed_by||""}
function activeWorkTarget(){return workView==="board"?$("work-board"):$("work-table")}
function workState(kind,title,detail){return `<div class="empty work-state" data-work-state="${esc(kind)}"><b>${esc(title)}</b><br>${esc(detail)}</div>`}
function normalizeWorkPayload(data){return {...(data||{}),work:Array.isArray(data&&data.work)?data.work:[],projects:Array.isArray(data&&data.projects)?data.projects:[],reviews:Array.isArray(data&&data.reviews)?data.reviews:[],loaded:true,error:null}}
function filteredWork(){const query=$("work-search").value.trim().toLowerCase(),status=$("status-filter").value,priority=$("priority-filter").value,project=$("project-filter").value;return workData.work.filter(item=>(!query||[item.title,item.request,item.brief,projectName(item.project_id),workOwner(item),...(item.tags||[])].some(value=>String(value||"").toLowerCase().includes(query)))&&(!status||normalStatus(item.status)===status)&&(!priority||item.priority===priority)&&(!project||item.project_id===project))}
function workCard(item){const deadline=workDeadline(item),blocked=item.blocking_reason?`<span class="work-chip blocked">Blocked</span>`:"",urgent=item.priority==="urgent"||item.priority==="high"?`<span class="work-chip urgent">${esc(item.priority)}</span>`:"";return `<button class="work-card" type="button" data-work-id="${esc(item.id)}" data-work-contract="dashboard-client-work" data-backend-route="/work/detail"><span class="card-eyebrow"><span>${esc(projectName(item.project_id))}</span><span>${esc(item.priority||"normal")}</span></span><strong>${esc(item.title)}</strong><span class="work-meta"><span>${esc(workOwner(item))}</span>${deadline?`<span class="work-chip">Due ${esc(deadline)}</span>`:""}${urgent}${blocked}</span></button>`}
function workTableRow(item){return `<tr data-work-id="${esc(item.id)}" data-work-row="list" data-work-contract="dashboard-client-work" data-backend-route="/work/detail" tabindex="0"><td><b>${esc(item.title||"Untitled work")}</b><span class="source-note">${esc(item.request||item.brief||"No request recorded")}</span></td><td>${esc(displayStatus(item.status))}</td><td>${esc(projectName(item.project_id))}</td><td>${esc(workOwner(item))}</td><td>${esc(item.priority||"normal")}</td><td>${esc(workDeadline(item)||"—")}</td><td>${item.blocking_reason?`<span class="work-chip blocked">Blocked</span>`:""}</td></tr>`}
function wireWorkSelection(container){container.querySelectorAll("[data-work-id]").forEach(node=>{node.onclick=()=>openWorkDetail(node.dataset.workId);node.onkeydown=event=>{if(node.tagName!=="BUTTON"&&event.key==="Enter")openWorkDetail(node.dataset.workId)}})}
function renderWork(){const board=$("work-board"),table=$("work-table"),scope=state.workspaces?.find(x=>x.id===workspace)?.name||"this workspace";board.hidden=workView!=="board";table.hidden=workView!=="list";if(!workData.loaded){$("work-summary").textContent=`Loading work in ${scope}`;activeWorkTarget().innerHTML=workState("loading","Loading work","Fetching /dashboard/client for this workspace.");return}if(workData.error){$("work-summary").textContent=`Work unavailable in ${scope}`;activeWorkTarget().innerHTML=workState("degraded","Work unavailable",workData.error);return}const items=filteredWork(),hasFilters=Boolean($("work-search").value.trim()||$("status-filter").value||$("priority-filter").value||$("project-filter").value);$("work-summary").textContent=`${items.length} item${items.length===1?"":"s"} in ${scope}`;if(!items.length){activeWorkTarget().innerHTML=workState("empty",hasFilters?"No matching work":"No work recorded",hasFilters?"Adjust or clear the search, status, priority, or project filters.":"The backend returned no work items for this workspace.");return}if(workView==="board"){const known=new Set(WORK_LANES.flatMap(lane=>lane.statuses)),lanes=[...WORK_LANES,{id:"other",label:"Other",statuses:[]}];board.innerHTML=lanes.map(lane=>{const cards=items.filter(item=>lane.id==="other"?!known.has(normalStatus(item.status)):lane.statuses.includes(normalStatus(item.status)));return `<section class="work-lane" data-lane="${lane.id}"><header class="lane-head"><span class="lane-label"><i class="lane-dot"></i>${lane.label} <span class="lane-count">${cards.length}</span></span><span aria-hidden="true">...</span></header><div class="lane-cards">${cards.length?cards.map(workCard).join(""):'<div class="work-empty">No work here</div>'}</div></section>`}).join("");wireWorkSelection(board)}else{table.innerHTML=`<table class="dense-table work-list-table" data-work-list-table><thead><tr><th>Work</th><th>Status</th><th>Project</th><th>Owner</th><th>Priority</th><th>Deadline</th><th>Blocker</th></tr></thead><tbody>${items.map(workTableRow).join("")}</tbody></table>`;wireWorkSelection(table)}}
function populateSelect(id,label,rows,value,display){const select=$(id),previous=select.value,options=[...new Set(rows.filter(Boolean))];select.innerHTML=`<option value="">${label}</option>`+options.map(row=>`<option value="${esc(value(row))}">${esc(display(row))}</option>`).join("");if([...select.options].some(option=>option.value===previous))select.value=previous}
function populateWorkFilters(){populateSelect("status-filter","All statuses",workData.work.map(x=>normalStatus(x.status)),x=>x,displayStatus);populateSelect("priority-filter","All priorities",workData.work.map(x=>x.priority),x=>x,x=>x);populateSelect("project-filter","All projects",workData.projects,x=>x.id,x=>x.name||x.id)}
async function loadWorkBoard(){workData={work:[],projects:[],reviews:[],loaded:false,error:null};renderWork();try{workData=normalizeWorkPayload(await api(`/dashboard/client?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}`));populateWorkFilters();renderWork()}catch(error){workData={work:[],projects:[],reviews:[],loaded:true,error:error.message||String(error)};renderWork();toast(error.message)}}
async function openWorkDetail(id){const modal=$("work-detail");$("detail-title").textContent="Loading work";$("detail-body").innerHTML='<div class="empty">Loading canonical record</div>';modal.showModal();try{const data=await api(`/work/detail?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}&work_item_id=${encodeURIComponent(id)}`),item=data.work_item;$("detail-status").textContent=displayStatus(item.status);$("detail-title").textContent=item.title;const fields=[["Project",projectName(item.project_id)],["Owner",item.owner_person_id||item.assignee_person_id||item.assignee_id||"Unassigned"],["Priority",item.priority||"normal"],["Deadline",item.deadline||item.needed_by||"Not set"],["Estimate",item.estimate_hours==null?"Not set":`${item.estimate_hours} hours`],["Actual",item.actual_effort_hours==null?"Not logged":`${item.actual_effort_hours} hours`]];$("detail-body").innerHTML=`<div class="detail-grid">${fields.map(([label,value])=>`<div class="detail-field"><span>${label}</span>${esc(value)}</div>`).join("")}</div><section class="detail-section"><h3>Request</h3><p>${esc(item.request||item.brief||"No request recorded")}</p></section>${item.blocking_reason?`<section class="detail-section"><h3>Blocker</h3><p>${esc(item.blocking_reason)}</p></section>`:""}<section class="detail-section"><h3>Activity</h3><ul>${(data.comments||[]).map(x=>`<li>${esc(x.body||x.comment||"Comment")}</li>`).join("")||'<li>No comments yet.</li>'}</ul></section><section class="detail-section"><h3>Evidence and files</h3><ul>${(data.files||[]).map(x=>`<li>${esc(x.title||x.url||x.id)}</li>`).join("")||'<li>No files attached.</li>'}</ul></section>`}catch(error){$("detail-body").innerHTML=`<div class="empty">${esc(error.message)}</div>`}}
function renderSpaces(){let holder=document.querySelector(".spaces");if(!holder){holder=document.createElement("section");holder.className="spaces";holder.innerHTML='<div class="spaces-head"><span>Workspaces</span><span>Scope</span></div><div class="space-list" id="space-list"></div>';document.querySelector(".scope").insertAdjacentElement("afterend",holder)}$("space-list").innerHTML=(state.workspaces||[]).map(item=>`<button class="space-button ${item.id===workspace?"active":""}" type="button" data-space-id="${esc(item.id)}"><i class="space-dot"></i><span>${esc(item.name)}<small>${esc(item.kind||item.role||"workspace")}</small></span></button>`).join("");document.querySelectorAll("[data-space-id]").forEach(button=>button.onclick=()=>{workspace=button.dataset.spaceId;renderSpaces();show("Work");loadWorkBoard()})}
async function bootstrapDashboard(){try{const identity=await api("/auth/me");org=identity.organization_id;person=identity.person_id;state=await api(`/dashboard/data?organization_id=${encodeURIComponent(org)}&person_id=${encodeURIComponent(person)}`);if(!state.workspaces?.some(x=>x.id===workspace)&&state.workspaces?.length)workspace=state.workspaces[0].id;render();renderSpaces();if(document.getElementById("page-work").classList.contains("active"))loadWorkBoard()}catch(error){toast(error.message)}}
const originalShow=show;show=function(name){originalShow(name);if(name==="Work")loadWorkBoard()};
function setWorkView(view){workView=view;$("board-view").classList.toggle("active",view==="board");$("list-view").classList.toggle("active",view==="list");$("board-view").setAttribute("aria-pressed",String(view==="board"));$("list-view").setAttribute("aria-pressed",String(view==="list"));renderWork()}
$("board-view").onclick=()=>setWorkView("board");$("list-view").onclick=()=>setWorkView("list");["work-search","status-filter","priority-filter","project-filter"].forEach(id=>$(id).addEventListener(id==="work-search"?"input":"change",renderWork));$("clear-work-filters").onclick=()=>{["work-search","status-filter","priority-filter","project-filter"].forEach(id=>$(id).value="");renderWork()};$("close-work-detail").onclick=()=>$("work-detail").close();setTimeout(()=>{if(state.workspaces?.length)renderSpaces()},500);
const brainPage=document.getElementById("page-brain"),brainGrid=brainPage&&brainPage.querySelector(".module-grid");async function loadBrainSurface(){if(!brainGrid)return;brainGrid.innerHTML='<div class="empty">Loading brain evidence</div>';try{const [brain,flows]=await Promise.all([api(`/dashboard/brain?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}`),api(`/dashboard/workflows?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}`)]);const proposals=brain.proposals||[],issues=(brain.health&&brain.health.issues)||[],facts=brain.facts||[],runs=flows.runs||[];brainGrid.innerHTML=`<section class="card module"><span class="state">Needs review · ${proposals.length}</span><h2>Proposal queue</h2><ul>${proposals.slice(0,6).map(x=>`<li>${esc(x.kind)} · ${esc(x.content||x.evidence||x.id)} · ${esc(x.status)}</li>`).join('')||'<li>Nothing waiting.</li>'}</ul></section><section class="card module"><span class="state">Open conflicts · ${issues.length}</span><h2>Knowledge health</h2><ul>${issues.slice(0,6).map(x=>`<li>${esc(x[0]||x.kind||x.type)} · ${esc(x[4]||x.message||x.reason||'Review')}</li>`).join('')||'<li>No open issues.</li>'}</ul></section><section class="card module"><span class="state">Trusted current · ${facts.length}</span><h2>Current truth</h2><ul>${facts.slice(0,6).map(x=>`<li>${esc(x.subject)} · ${esc(x.predicate)} · ${esc(x.object)}</li>`).join('')||'<li>No current facts.</li>'}</ul></section><section class="card module" style="grid-column:1/-1"><span class="state">Workflow map · ${runs.length}</span><h2>Stage board</h2><div class="work-board">${runs.map(x=>`<article class="card"><b>${esc(x.definition_name||x.definition_key)}</b><p class="sub">${esc(x.status)} · ${esc(x.due_at||'No due date')}</p></article>`).join('')||'<div class="empty">No workflow runs in this workspace.</div>'}</div></section>`}catch(error){brainGrid.innerHTML=`<div class="empty">Brain unavailable: ${esc(error.message)}</div>`}}const surfaceShow=show;show=function(name){surfaceShow(name);if(name==="Brain"||name==="Workflows")loadBrainSurface()};
loadBrainSurface=async function(){if(!brainGrid)return;brainGrid.innerHTML='<div class="empty">Loading brain evidence</div>';try{const [brain,flows]=await Promise.all([api(`/dashboard/brain?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}&as_of=${encodeURIComponent(brainAsOf||'')}`),api(`/dashboard/workflows?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}&as_of=${encodeURIComponent(brainAsOf||'')}`)]);const proposals=brain.proposals||[],issues=(brain.health&&brain.health.issues)||[],truths=brain.current_truths||[],runs=flows.runs||[],stages=flows.stages||[];brainGrid.innerHTML=`<section class="card module"><span class="state">Needs review · ${proposals.length}</span><h2>Proposal queue</h2><ul>${proposals.slice(0,6).map(x=>`<li>${esc(x.kind||x.type)} · ${esc(x.content||x.evidence||x.id)} · ${esc(x.status)}</li>`).join('')||'<li>Nothing waiting.</li>'}</ul></section><section class="card module"><span class="state">Open conflicts · ${issues.length}</span><h2>Knowledge health</h2><ul>${issues.slice(0,6).map(x=>`<li>${esc(x.kind||x.type||x[0])} · ${esc(x.message||x.reason||x[4]||'Review')}</li>`).join('')||'<li>No open issues.</li>'}</ul></section><section class="card module"><span class="state">Trusted current · ${truths.length}</span><h2>Current truth</h2><ul>${truths.slice(0,6).map(x=>`<li>${esc(x.subject||x.name||x.id)} · ${esc(x.predicate||x.state||'Current')} · ${esc(x.object||x.value||'')}</li>`).join('')||'<li>No current facts.</li>'}</ul></section><section class="card module" style="grid-column:1/-1"><span class="state">Workflow map · ${runs.length}</span><h2>Stage board</h2><div class="work-board">${runs.map(x=>`<article class="card"><b>${esc(x.definition_name||x.definition_key)}</b><p class="sub">${esc(x.status)} · ${esc(x.due_at||'No due date')}</p></article>`).join('')||'<div class="empty">No workflow runs in this workspace.</div>'}</div><p class="sub">${stages.length} stage records · read-only historical view</p></section>`}catch(error){brainGrid.innerHTML=`<div class="empty">Brain unavailable: ${esc(error.message)}</div>`}};
loadBrainSurface=async function(){if(!brainGrid)return;brainGrid.innerHTML='<div class="empty">Loading brain evidence</div>';try{const [brain,flows]=await Promise.all([api(`/dashboard/brain?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}`),api(`/dashboard/workflows?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}`)]);const proposals=brain.proposals||[],conflicts=brain.conflicts||[],truths=brain.current_truths||[],runs=flows.runs||[],stages=flows.stages||[],semantic=brain.health&&brain.health.semantic||{},graph=brain.health&&brain.health.graph||{};const stageLanes=stages.map(x=>`<article class="card"><b>${esc(x.name||x.id||'Stage')}</b><p class="sub">${esc(x.status||x.readiness||'Pending')} · ${esc(x.due||'No due date')}</p></article>`).join('');brainGrid.innerHTML=`<section class="card module"><span class="state">Needs review · ${proposals.length}</span><h2>Proposal queue</h2><ul>${proposals.slice(0,6).map(x=>`<li>${esc(x.kind||x.type)} · ${esc(x.content||x.evidence||x.id)} · ${esc(x.status)}</li>`).join('')||'<li>Nothing waiting.</li>'}</ul></section><section class="card module"><span class="state">Open conflicts · ${conflicts.length}</span><h2>Knowledge health</h2><p class="sub">Semantic: ${esc(semantic.status||'unknown')} · Graph: ${esc(graph.status||'unknown')}</p><ul>${conflicts.slice(0,6).map(x=>`<li>${esc(x.conflict_group||x.kind||x.id)} · ${esc(x.reason||x.status||'Review')}</li>`).join('')||'<li>No open conflicts.</li>'}</ul></section><section class="card module"><span class="state">Trusted current · ${truths.length}</span><h2>Current truth</h2><ul>${truths.slice(0,6).map(x=>`<li>${esc(x.subject||x.name||x.id)} · ${esc(x.predicate||x.state||'Current')} · ${esc(x.object||x.value||'')}</li>`).join('')||'<li>No current truths.</li>'}</ul></section><section class="card module" style="grid-column:1/-1"><span class="state">Workflow map · ${runs.length} runs · ${stages.length} stages</span><h2>Stage board</h2><div class="work-board">${stageLanes||'<div class="empty">No workflow stages in this workspace.</div>'}</div><p class="sub">Read-only board; actions remain capability-gated.</p></section>`}catch(error){brainGrid.innerHTML=`<div class="empty">Brain unavailable: ${esc(error.message)}</div>`}};
async function loadWorkflowSurface(){const target=$("system-modules");if(!target)return;target.innerHTML='<div class="empty">Loading workflow board</div>';try{const data=await api(`/dashboard/workflows?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}`),stages=data.stages||[];const lanes={pending:[],ready:[],in_progress:[],waiting_approval:[],blocked:[],completed:[]};stages.forEach(stage=>{const key=String(stage.readiness&&stage.readiness.ready?"ready":stage.status||"pending").toLowerCase().replaceAll(" ","_");(lanes[key]||lanes.pending).push(stage)});target.innerHTML=`<section class="card module" style="grid-column:1/-1"><span class="state">Workflow stage board · ${stages.length}</span><div class="work-board">${Object.entries(lanes).map(([name,items])=>`<section class="card"><h2>${esc(name.replaceAll("_"," "))} · ${items.length}</h2>${items.map(stage=>{const due=stage.due&&typeof stage.due==='object'?stage.due.at:stage.due;const readiness=stage.readiness&&stage.readiness.ready?'Ready':stage.status||'Pending';return `<article class="card"><b>${esc(stage.name||stage.id||'Stage')}</b><p class="sub">${esc(readiness)} · Due ${esc(due||'—')}</p></article>`}).join('')||'<p class="sub">No stages</p>'}</section>`).join('')}</div></section>`}catch(error){target.innerHTML=`<div class="empty">Workflow board unavailable: ${esc(error.message)}</div>`}}
const routedShow=show;show=function(name){routedShow(name);if(name==="Brain")loadBrainSurface();if(name==="Workflows")loadWorkflowSurface()};
/* Brain queue contract: status==="pending" only; conflicts||[] are unresolved; due is normalized with typeof stage.due. */
loadBrainSurface=async function(){if(!brainGrid)return;brainGrid.innerHTML='<div class="empty">Loading brain evidence</div>';try{const [brain,flows]=await Promise.all([api(`/dashboard/brain?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}`),api(`/dashboard/workflows?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}`)]);const pending=(brain.proposals||[]).filter(item=>item.status==="pending"),conflicts=(brain.conflicts||[]).filter(item=>item.state==="conflicted"),truths=brain.current_truths||[],semantic=brain.health&&brain.health.semantic||{},graph=brain.health&&brain.health.graph||{},stages=flows.stages||[];brainGrid.innerHTML=`<section class="card module"><span class="state">Needs review · ${pending.length}</span><h2>Pending proposals</h2><ul>${pending.map(item=>`<li>${esc(item.kind||item.type)} · ${esc(item.content||item.id)}</li>`).join('')||'<li>Nothing waiting.</li>'}</ul></section><section class="card module"><span class="state">Open conflicts · ${conflicts.length}</span><h2>Conflicts</h2><p class="sub">Semantic: ${esc(semantic.status||'unknown')} · Graph: ${esc(graph.status||'unknown')}</p><ul>${conflicts.map(item=>`<li>${esc(item.conflict_group||item.id)} · conflicted</li>`).join('')||'<li>No open conflicts.</li>'}</ul></section><section class="card module"><span class="state">Trusted current · ${truths.length}</span><h2>Current truth</h2><ul>${truths.map(item=>`<li>${esc(item.subject||item.name||item.id)} · ${esc(item.predicate||item.state||'Current')} · ${esc(item.object||item.value||'')}</li>`).join('')||'<li>No current truths.</li>'}</ul></section><section class="card module" style="grid-column:1/-1"><span class="state">Workflow stages · ${stages.length}</span><p class="sub">Current view · semantic ${esc(semantic.status||'unknown')} · graph ${esc(graph.status||'unknown')}</p></section>`}catch(error){brainGrid.innerHTML=`<div class="empty">Brain unavailable: ${esc(error.message)} <button class="ghost" type="button" onclick="loadBrainSurface()">Retry</button></div>`}};
function renderAllowedActions(row){if(!row||row.historical||!Array.isArray(row.allowed_actions)||!row.allowed_actions.length)return '';return row.allowed_actions.map(action=>`<button class="ghost" type="button" data-action="${esc(action)}" data-row-id="${esc(row.id||'')}" data-expected-version="${esc(row.version||'')}">${esc(String(action).replaceAll('_',' '))}</button>`).join('')}
async function executeDashboardAction(action,row){const dialog=document.getElementById('dashboard-action-dialog')||(()=>{const d=document.createElement('dialog');d.id='dashboard-action-dialog';d.innerHTML='<form method="dialog" class="form"><h2 id="dashboard-action-title"></h2><label>Reason<textarea id="dashboard-action-reason"></textarea></label><label>Evidence<textarea id="dashboard-action-evidence"></textarea></label><div class="row"><button class="ghost" value="cancel">Cancel</button><button class="action" id="dashboard-action-confirm" value="default">Confirm</button></div></form>';document.body.appendChild(d);return d})();dialog.querySelector('#dashboard-action-title').textContent=String(action).replaceAll('_',' ');dialog.showModal();const form=dialog.querySelector('form');form.onsubmit=async event=>{event.preventDefault();const key=`dashboard:${action}:${row.id||'unknown'}:${row.version||''}`;try{const endpoint=action.includes('conflict')?'/brain/conflicts/resolve':action.includes('promot')?'/brain/promote':'/workflows/stages/'+action;const body={workspace_id:workspace,action,proposal_id:row.id,conflict_group:row.conflict_group,winner_fact_id:row.winner_fact_id,stage_id:row.id,expected_version:row.version,reason:dialog.querySelector('#dashboard-action-reason').value,evidence:dialog.querySelector('#dashboard-action-evidence').value,idempotency_key:key};await api(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});dialog.close();if(typeof loadBrainSurface==='function')loadBrainSurface();if(typeof loadWorkflowSurface==='function')loadWorkflowSurface()}catch(error){toast(error.message)}}};document.addEventListener('click',event=>{const button=event.target.closest('[data-action]');if(button)executeDashboardAction(button.dataset.action,{id:button.dataset.rowId,version:button.dataset.expectedVersion})});
function renderActionDescriptors(row){if(!row||row.historical||!Array.isArray(row.allowed_actions))return '';return row.allowed_actions.map(descriptor=>{const action=typeof descriptor==='string'?{action:descriptor,method:'POST',route:'',payload:{},required_fields:[]}:descriptor||{},label=esc(action.action||action.label||'Action');return action.route?`<button class="ghost" type="button" data-action-descriptor="${esc(JSON.stringify(action))}">${label}</button>`:`<button class="ghost" type="button" disabled title="No backend route is available">${label} unavailable</button>`}).join('')}
function actionDescriptorInput407(name){if(name==='title')return `<label>Task title<input data-action-field="${esc(name)}" required></label>`;if(name==='instructions')return `<label>Task instructions<textarea data-action-field="${esc(name)}" required></textarea></label>`;return `<label>${esc(name)}<textarea data-action-field="${esc(name)}" required></textarea></label>`}
async function executeDescriptorAction(descriptor){const dialog=document.getElementById('dashboard-action-dialog');if(!dialog)return;dialog.querySelector('#dashboard-action-title').textContent=descriptor.action||'Action';dialog.showModal();const form=dialog.querySelector('form');form.onsubmit=async event=>{event.preventDefault();const payload={...(descriptor.payload||{})};(descriptor.required_fields||[]).forEach(field=>{if(field==='reason')payload.reason=dialog.querySelector('#dashboard-action-reason').value;if(field==='evidence')payload.evidence=dialog.querySelector('#dashboard-action-evidence').value});try{await api(descriptor.route,{method:descriptor.method||'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});dialog.close();loadBrainSurface();loadWorkflowSurface()}catch(error){toast(error.message)}}}
