const priorBrainLoad=loadBrainSurface,priorWorkflowLoad=loadWorkflowSurface;loadBrainSurface=async function(){await priorBrainLoad();try{const data=await api(`/dashboard/brain?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}`);injectDescriptorButtons(data.proposals,'#page-brain .module');injectDescriptorButtons(data.conflicts,'#page-brain .module')}catch(_error){}};loadWorkflowSurface=async function(){await priorWorkflowLoad();try{const data=await api(`/dashboard/workflows?organization_id=${encodeURIComponent(org)}&workspace_id=${encodeURIComponent(workspace)}&person_id=${encodeURIComponent(person)}`);injectDescriptorButtons(data.stages,'#system-modules .module')}catch(_error){}};
function ensureDashboardActionDialog(){let dialog=document.getElementById('dashboard-action-dialog');if(dialog)return dialog;dialog=document.createElement('dialog');dialog.id='dashboard-action-dialog';dialog.innerHTML='<form method="dialog" class="form"><h2 id="dashboard-action-title"></h2><div id="dashboard-action-fields"></div><div class="row"><button class="ghost" value="cancel">Cancel</button><button class="action" id="dashboard-action-confirm" value="default">Confirm</button></div></form>';document.body.appendChild(dialog);return dialog}
executeDescriptorAction=async function(descriptor){const dialog=ensureDashboardActionDialog(),fields=dialog.querySelector('#dashboard-action-fields');dialog.querySelector('#dashboard-action-title').textContent=descriptor.action||'Action';fields.innerHTML=(descriptor.required_fields||[]).map(field=>{const name=typeof field==='string'?field:field.name||field.field||'';if(name.startsWith('one_of:'))return `<label>${esc(name)}<input required data-action-field="${esc(name)}" placeholder="${esc(name.slice(7).replaceAll(',',' / '))}"></label>`;return `<label>${esc(name)}<textarea data-action-field="${esc(name)}" ${name==='reason'||name==='kind'?'required':''}></textarea></label>`}).join('');dialog.showModal();const form=dialog.querySelector('form');form.onsubmit=async event=>{event.preventDefault();const payload={...(descriptor.payload||{})};let valid=true;fields.querySelectorAll('[data-action-field]').forEach(input=>{const key=input.dataset.actionField;const value=input.value.trim();if(key.startsWith('one_of:')){if(!value)valid=false;else payload[key.slice(7).split(',')[0]]=value}else payload[key]=value});if(!valid){toast('Complete the required evidence field');return}try{payload.idempotency_key=payload.idempotency_key||`dashboard:${descriptor.route}:${payload.proposal_id||payload.stage_id||Date.now()}`;await api(descriptor.route,{method:descriptor.method||'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});dialog.close();if(typeof loadBrainSurface==='function')loadBrainSurface();if(typeof loadWorkflowSurface==='function')loadWorkflowSurface()}catch(error){toast(error.message)}}}
