const priorEntityBrainLoad=loadBrainSurface;
function entityWorkspaceLabel(){const item=(state.workspaces||[]).find(x=>x.id===workspace);return item&&item.name?item.name:workspace}
function entityEvidenceSummary(refs){const groups=Object.entries(refs||{}).filter(([,ids])=>Array.isArray(ids)&&ids.length);if(!groups.length)return 'No visible provenance references';return groups.map(([kind,ids])=>`${ids.length} ${kind}`).join(' · ')}
function entityCandidateAction(candidate){return Array.isArray(candidate&&candidate.allowed_actions)?candidate.allowed_actions.find(action=>{const item=typeof action==='string'?{action}:action;return item&&item.route&&/propos/i.test(item.action||'')}):null}
function renderEntityCandidate(candidate){const entity=candidate&&candidate.entity||{},refs=candidate&&candidate.evidence_refs||{},action=entityCandidateAction(candidate);return `<article class="card entity-candidate"><div class="row" style="justify-content:space-between;gap:12px"><div><b>${esc(entity.canonical_name||entity.name||entity.id||'Unnamed entity')}</b><p class="sub">${esc(entity.type||'Entity')} · match score ${esc(Number(candidate.score||0).toFixed(2))}</p></div>${action?`<button class="ghost" type="button" data-action-descriptor="${esc(JSON.stringify(action))}">${esc(action.label||action.action||'Propose alias')}</button>`:''}</div><p class="sub">Reasons: ${esc((candidate.reasons||[]).join(' · ')||'Evidence-backed name variant')}</p><p class="sub">Provenance: ${esc(entityEvidenceSummary(refs))}</p>${Object.keys(refs).some(key=>Array.isArray(refs[key])&&refs[key].length)?`<details><summary>View citations</summary><ul>${Object.entries(refs).flatMap(([kind,ids])=>(ids||[]).slice(0,6).map(id=>`<li>${esc(kind)} · ${esc(id)}</li>`)).join('')}</ul></details>`:''}</article>`}
function renderEntityResolutionShell(){if(!brainGrid)return;const existing=brainGrid.querySelector('[data-entity-resolution]');if(existing)return existing;brainGrid.insertAdjacentHTML('afterbegin',`<section class="card module" data-entity-resolution style="grid-column:1/-1"><span class="state">Scoped discovery · ${esc(entityWorkspaceLabel())}</span><h2>Entity resolution</h2><p class="sub">Find evidence-backed name or domain variants in this workspace. Discovery never proposes or merges automatically.</p><form class="row" data-entity-resolution-form><label style="flex:1;min-width:220px">Name or domain<input name="entity-name" autocomplete="off" placeholder="e.g. client.example.com or Client Name"></label><button class="action" type="submit">Discover candidates</button></form><div class="empty" data-entity-resolution-results>Enter a name or domain to begin.</div></section>`);const section=brainGrid.querySelector('[data-entity-resolution]'),form=section.querySelector('[data-entity-resolution-form]');form.addEventListener('submit',async event=>{event.preventDefault();const input=form.elements.namedItem('entity-name'),query=String(input.value||'').trim(),results=section.querySelector('[data-entity-resolution-results]');if(!query){results.className='empty';results.textContent='Enter a name or domain to begin.';return}results.className='empty';results.textContent='Searching scoped evidence…';try{const payload=await api(`/entity/candidates?workspace_id=${encodeURIComponent(workspace)}&name=${encodeURIComponent(query)}&limit=8`),candidates=Array.isArray(payload.candidates)?payload.candidates:[];if(!candidates.length){results.className='empty';results.textContent='No evidence-backed candidates found in this workspace.';return}results.className='entity-candidate-list';results.innerHTML=candidates.map(renderEntityCandidate).join('');results.querySelectorAll('[data-action-descriptor]').forEach(button=>button.addEventListener('click',()=>executeDescriptorAction(JSON.parse(button.dataset.actionDescriptor))))}catch(error){results.className='empty';results.textContent=`Entity discovery unavailable: ${error.message}`}});return section}
