  function brainDetail(row,kind){if(!row)return '<div class="empty">Select a knowledge record to inspect its evidence and context.</div>';const entries=Object.entries(row).filter(([key,value])=>value!==null&&value!==undefined&&value!==''&&!['allowed_actions','structured_payload'].includes(key)).slice(0,14);const period=row.valid_from||row.effective_from||row.valid_period||row.effective_until;const observed=row.observed_at||row.observation_date||row.recorded_at||row.created_at;const provenance=row.evidence_span||row.evidence||row.citation&&row.citation.evidence_span||'No evidence span returned';const history=row.history||row.versions||row.superseded_by||'No prior versions returned';return `<div class="brain-detail-head"><span class="state">${esc(brainKind(row))}</span><h2>${esc(brainText(row))}</h2><p class="sub">${esc(brainSource(row))} · ${esc(row.state||row.status||'recorded')}</p></div><div class="brain-provenance-grid"><div class="detail-field"><span>Validity</span><div>${esc(period||'Not specified')}</div></div><div class="detail-field"><span>Observed</span><div>${esc(observed||'Not specified')}</div></div><div class="detail-field"><span>Confidence</span><div>${esc(row.confidence??'Not calibrated')}</div></div><div class="detail-field"><span>Evidence span</span><div>${esc(provenance)}</div></div><div class="detail-field"><span>Related entities</span><div>${esc(row.related_entities||row.entities||'None returned')}</div></div><div class="detail-field"><span>Affected decisions</span><div>${esc(row.affected_decisions||'None returned')}</div></div><div class="detail-field"><span>History</span><div>${esc(typeof history==='object'?JSON.stringify(history):history)}</div></div></div><div class="brain-detail-grid">${entries.map(([key,value])=>`<div class="detail-field"><span>${esc(key.replaceAll('_',' '))}</span><div>${esc(typeof value==='object'?JSON.stringify(value):value)}</div></div>`).join('')}</div>${Array.isArray(row.allowed_actions)&&row.allowed_actions.length?'<p class="sub" style="margin-top:16px">Available actions are shown only when the server grants them.</p>':''}`}
